    "tolerans": 0,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Vilket av mätvärdena begränsar antalet värdesiffror i kvoten?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true,
    "svarFormat": "numeriskt",
    "svarEnhet": "g/cm³"
