    "tolerans": 0,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Hur mycket energi ryms i en kubikmeter om du känner energin per liter?</p>",
    "traningsniva": 2,
