    "geogebra": false,
    "ledtrad": "<p>Hur stor del av sensorbredden upptar en bildpunkt?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true,
    "svarFormat": "numeriskt",
