    "rättSvar": null,
    "tolerans": null,
    "självrättning": false,
    "familjNyckelTidigare": "densitet__densitet_med_geometrisk_volym",
    "ledtrad": "<p>Jämför den väntade volymändringen med mätglasets minsta skalsteg.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "miniräknare": true,
