    "självrättning": false,
    "familjNyckelTidigare": "densitet__densitet_med_geometrisk_volym",
    "ledtrad": "<p>Hur mycket metall motsvarar föremålets massa enligt huvudseriens lutning?</p>",
    "spel": false,
    "traningsniva": 4,
    "arbetsinsats": 2,
    "miniräknare": true,
    "geogebra": false,
    "manuellKomplettering": true,
