    "ledtrad": "<p>Hur kan ett känt startläge kombineras med hastighetsdiagrammets area?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "miniräknare": true,
    "geogebra": false,
    "spel": true,
    "svarEnhet": "m",
    "svarFormat": "numeriskt",
    "familjTidigare": [
      "Lodrät kast och fritt fall"
    ]
