    "tolerans": null,
    "självrättning": false,
    "spel": false,
    "familjNyckelTidigare": "diagram__tolka_och_rita_vt_diagram",
    "ledtrad": "<p>Bakåtrörelsen ska ligga under tidsaxeln i hastighetsdiagrammet.</p>",
    "traningsniva": 3,
    "arbetsinsats": 1,
    "miniräknare": true,
    "geogebra": false,
