    "tolerans": 0,
    "självrättning": true,
    "ledtrad": "<p>Vilka krafter ger motsatta moment kring stödet?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "miniräknare": true,
    "geogebra": false,
    "spel": true,
    "svarEnhet": "N",
