    "rättSvar": null,
    "tolerans": null,
    "självrättning": false,
    "ledtrad": "<p>Vad säger noll kraftresultant om accelerationen – och vad säger den inte om farten?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "geogebra": false,
    "miniräknare": true,
