    "familjNyckelFöreHierarki": "newton__newtons_lagar_i_hiss",
    "ledtrad": "<p>Vilka föremål växelverkar pucken med efter att knuffen upphört?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "geogebra": false,
