    "familjNyckelFöreHierarki": "newton__newtons_lagar_i_hiss",
    "ledtrad": "<p>Vilka vagnar behöver accelereras av varje koppel?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "geogebra": false,
    "miniräknare": true,
