    "självrättning": false,
    "spel": false,
    "familjNyckelTidigare": "ritakrafter__frilaggning_med_spannkraft",
    "ledtrad": "<p>Vad säger konstant hastighet om accelerationen?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "miniräknare": true,
