    "tolerans": null,
    "självrättning": false,
    "spel": false,
    "familjNyckelTidigare": "ritakrafter__frilaggning_pa_lutande_plan",
    "ledtrad": "<p>Vilken del av tyngdkraften är vinkelrät mot underlaget?</p>",
    "traningsniva": 3,
