    "ledtrad": "<p>Är den sökta kraften hela resultanten eller en av krafterna?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "spel": true,
    "svarEnhet": "N",
    "svarFormat": "numeriskt",
    "typfamilj": "Bestämma dragkraft",
