    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Vilket tecken har accelerationen när uppåtrörelsen bromsas?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "N",
    "svarFormat": "numeriskt",
    "typfamilj": "Kraft i hiss",
