    "geogebra": false,
    "ledtrad": "<p>Hur kan radien och densiteten användas för att bestämma massan?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "m/s²",
