    "rättSvar": null,
    "tolerans": null,
    "självrättning": false,
    "spel": false,
    "familjNyckelTidigare": "ritakrafter__frilaggning_med_spannkraft",
    "ledtrad": "<p>Betrakta det nya jämviktsläget när den tyngre klossen har stannat.</p>",
    "traningsniva": 2,
