    "geogebra": false,
    "ledtrad": "<p>Vilket värde måste den andra fjädern bidra med i seriekopplingens samband?</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "N/m",
    "svarFormat": "numeriskt",
    "typfamilj": "Välja fjäder till en koppling",
