    "familjNyckelFöreHierarki": "newton__newtons_lagar_i_hiss",
    "ledtrad": "<p>Dela varje kabelkraft i en bakåtkomponent och en sidokomponent.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "miniräknare": true,
    "geogebra": false,
    "spel": false,
    "manuellKomplettering": true,
    "omrTidigare": "newton"
