    "tolerans": null,
    "självrättning": false,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Åt vilket håll skulle lådan förskjutas relativt flaket om friktionen saknades?</p>",
    "spel": false,
    "traningsniva": 3,
    "arbetsinsats": 2,
    "manuellKomplettering": true,
    "typfamilj": "Friktion vid inbromsning",
    "omrTidigare": "ritakrafter",
