    "tolerans": null,
    "självrättning": false,
    "spel": false,
    "familjNyckelTidigare": "ritakrafter__frilaggning_med_friktion",
    "ledtrad": "<p>Vilken riktning är vinkelrät ut från väggen?</p>",
