    "tolerans": null,
    "självrättning": false,
    "spel": false,
    "familjNyckelTidigare": "ritakrafter__frilaggning_med_spannkraft",
    "ledtrad": "<p>Har bollen fortfarande kontakt med den som kastade den?</p>",
    "traningsniva": 2,
    "arbetsinsats": 1,
    "miniräknare": true,
    "geogebra": false,
    "manuellKomplettering": true,
    "typfamilj": "Krafter efter ett kast",
