    "omrTidigare": "blandat",
    "familjNyckelFöreHierarki": "blandat__rorelsemangd_och_impuls",
    "ledtrad": "<p>Jämför en kraft som är stor tidigt med en som är stor sent.</p>",
    "traningsniva": 4,
    "miniräknare": true,
    "geogebra": false,
