    "självrättning": false,
    "omrTidigare": "blandat",
    "familjNyckelFöreHierarki": "blandat__rorelsemangd_och_impuls",
    "ledtrad": "<p>Behandla kastet och fångsten som två olika händelser med olika system.</p>",
    "traningsniva": 4,
