    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Vilken total massa kan den nyttiga effekten höja, och hur mycket av den är själva plattformen?</p>",
    "traningsniva": 4,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "kg",
    "svarFormat": "numeriskt",
