    "självrättning": false,
    "omrTidigare": "blandat",
    "familjNyckelFöreHierarki": "blandat__mekanisk_energi",
    "ledtrad": "<p>Skilj på grafens höjd, lutning och arean under grafen.</p>",
    "traningsniva": 3,
    "miniräknare": true,
    "geogebra": false,
    "arbetsinsats": 2,
    "spel": false,
    "manuellKomplettering": true,
