    "s": "<p>p = 100+12 = 112 kPa. Svar: 112 kPa.</p>",
    "niva": "E",
    "traningsniva": 1,
    "familj": "Absoluttryck, övertryck och lufttryck",
    "typ": "absoluttryck i vätska",
    "ledtrad": "<p>Lägg till tryckökningen till yttrycket.</p>",
    "miniräknare": true,
