    "tolerans": null,
    "självrättning": false,
    "ledtrad": "<p>Skilj mellan statiskt tryck och tryck när vatten strömmar.</p>",
    "traningsniva": 3,
    "typ": "statiskt tryck i ledning",
    "miniräknare": true,
