    "tolerans": 0,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Räkna bort både gasens och höljets massa från den undanträngda luftens massa.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "g",
