    "tolerans": 0,
    "självrättning": true,
    "ledtrad": "<p>Bestäm först klossens densitet med hjälp av läget i sötvatten.</p>",
    "traningsniva": 3,
    "miniräknare": true,
    "geogebra": false,
    "arbetsinsats": 2,
    "spel": true,
    "svarEnhet": "%",
    "svarFormat": "numeriskt",
