    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Tänk på definitionen och på storheternas riktningar eller tecken.</p>",
    "alternativ": [
      {
        "txt": "Polspänningen är lägre än ems.",
        "ratt": true,
        "kommentar": "En del av ems faller över den inre resistansen."
      },
      {
        "txt": "Polspänningen är alltid högre än ems.",
        "ratt": false,
        "kommentar": "Det gäller inte när batteriet levererar ström."
      },
      {
        "txt": "Polspänningen är alltid exakt noll.",
        "ratt": false,
        "kommentar": "Endast i ett särskilt idealiserat kortslutningsfall kan den närma sig noll."
      },
      {
        "txt": "Inre resistans påverkar inte polspänningen.",
        "ratt": false,
        "kommentar": "Den ger spänningsfallet Ir."
      }
    ],
