    "geogebra": false,
    "ledtrad": "<p>Vilka storheter är givna och vilket samband kopplar ihop dem?</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "µC",
    "traningsniva": 2,
    "arbetsinsats": 1,
