    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>I serie adderas resistanser. I parallell adderas deras inverser.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "Ω",
    "traningsniva": 1,
