    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Omvandla först \\(18\\,\\mathrm{kN/C}\\) till \\(\\mathrm{N/C}\\).</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "µC",
    "traningsniva": 2,
