    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Räkna den inre resistansen som en serieresistans med belastningen.</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "A",
    "traningsniva": 3,
