    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Den inre resistansen värms av strömmen enligt \\(P=I^2R\\).</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "W",
