    "svarstyp": "numeriskt",
    "rättSvar": 526640.62,
    "tolerans": 9479.53125,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Rita först fältriktningen från vardera laddningen i mittpunkten.</p>",
    "svarFormat": "numeriskt",
