    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Koppla ihop laddning, potentialskillnad och energi med \\(\\Delta E_p=qU\\).</p>",
    "svarFormat": "numeriskt",
    "svarEnhet": "keV",
    "traningsniva": 3,
    "arbetsinsats": 1,
