    "tolerans": 5797406001.849986,
    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Tre steg: massa → substansmängd → antal kärnor → aktivitet.</p>",
    "svarFormat": "numeriskt",
