    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>När volymen halveras vid konstant temperatur ändras trycket med den omvända faktorn.</p>",
    "traningsniva": 1,
    "typ": "boyles lag och förändringsfaktor",
    "arbetsinsats": 1,
    "spel": true,
    "svarEnhet": "kPa",
