    "geogebra": false,
    "svarFormat": "numeriskt",
    "svarEnhet": "Ω",
    "ledtrad": "<p>För en homogen ledare gäller \\(R=\\rho L/A\\). Resistiviteten är given i SI-enheter, så tvärsnittsarean måste först skrivas i \\(\\mathrm{m^2}\\).</p>",
    "traningsniva": 3,
    "arbetsinsats": 1,
    "spel": true
