    "självrättning": true,
    "formaga": [
      "problemlösning",
      "modellering"
    ],
    "svarFormat": "numeriskt",
    "ledtrad": "<p>X har friktion både mot Y och mot bordet.</p>",
    "traningsniva": 4,
    "familjNyckel": "newton1__snorkrafter_och_jamvikt",
    "arbetsinsats": 2,
