    "självrättning": true,
    "miniräknare": true,
    "geogebra": false,
    "ledtrad": "<p>Använd vattnet för att bestämma den gemensamma fyllnadsvolymen.</p>",
    "traningsniva": 3,
    "arbetsinsats": 2,
    "spel": true,
