    "rättSvar": 15.6,
    "tolerans": 0.3,
    "självrättning": true,
    "ledtrad": "<p>Vilken komposant motsvarar ökningen i höjd? Ligger den intill eller mitt emot vinkeln?</p>",
    "traningsniva": 3,
    "arbetsinsats": 1,
    "miniräknare": true,
